import{_ as d,o as a,c as r,ag as p}from"./chunks/framework.CD3EN-rd.js";const _=JSON.parse('{"title":"第3章 建设工程招标投标与合同管理","description":"","frontmatter":{"title":"第3章 建设工程招标投标与合同管理","layout":"doc","order":4},"headers":[],"relativePath":"考试/一级建造师/工程管理/第3章 建设工程招标投标与合同管理.md","filePath":"考试/一级建造师/工程管理/第3章 建设工程招标投标与合同管理.md","lastUpdated":1767119520000}'),o={name:"考试/一级建造师/工程管理/第3章 建设工程招标投标与合同管理.md"};function e(n,t,s,l,b,i){return a(),r("div",null,[...t[0]||(t[0]=[p('<h1 id="第3章-建设工程招标投标与合同管理" tabindex="-1">第3章  建设工程招标投标与合同管理 <a class="header-anchor" href="#第3章-建设工程招标投标与合同管理" aria-label="Permalink to &quot;第3章  建设工程招标投标与合同管理&quot;">​</a></h1><h2 id="_3-1-工程招标投标" tabindex="-1">3.1  工程招标投标 <a class="header-anchor" href="#_3-1-工程招标投标" aria-label="Permalink to &quot;3.1  工程招标投标&quot;">​</a></h2><h3 id="考点1-招标方式与程序【a】" tabindex="-1">考点1：招标方式与程序【A】 <a class="header-anchor" href="#考点1-招标方式与程序【a】" aria-label="Permalink to &quot;考点1：招标方式与程序【A】&quot;">​</a></h3><p><strong>1.招标方式</strong></p><p>根据《民法典》，要约和承诺是订立合同的必经环节。</p><p>①要约邀请：建设单位招标；②要约：施工单位投标；③承诺：建设单位发中标通</p><p>知书。</p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1760711738475.png" alt="" loading="lazy"></p><p><strong>2.招标程序</strong></p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1760711768485.png" alt="" loading="lazy"></p><p>招标程序【时间总结】</p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1760711786480.png" alt="image-20251017223626427" loading="lazy"></p><p>【进行资格预审】</p><p>②发售资格预审文件发售期不得少于5日；</p><p>有异议应在提交资格预审申请文件截止时2日前提出；招标人收到异议之日起3日内答复，答复前暂停招标投标活动。</p><p>③资格预审文件的澄清或修改</p><p>招标人应在提交资格预审申请文件截止时间至少3日前，以 书面形式通知所有获取资格预审文件的潜在投标人；</p><p>不足3日的，顺延提交资格预审申请文件的截止时间。【发售招标文件和组织现场踏勘】</p><p>招标人对招标文件进行澄清或者修改的内容可能影响投标文件编制的，招标人应在投标截止时间至少15日前，以书面形式通知所有获取招标文件的潜在投标人；</p><p>不足15日的，招标人应顺延提交投标文件的截止时间。【确定中标人】</p><p>招标人依据评标委员会推荐的中标候选人确定中标人；</p><p>向中标人发出中标通知书，同时将中标结果通知未中标的投标人。【签订合同】</p><p>应在中标通知书发出之日起30日内，根据招标文件和中标人的投标文件订立书面合同。</p><p>招标人最迟应在书面合同签订后5日内向所有投标人退还投标保证金及银行同期存款利息。</p><p>中标人无正当理由拒签合同的，其投标保证金不予退还。</p><p>【资格预审VS评标】</p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1760713034950.png" alt="image-20251017225714899" loading="lazy"></p><p>【资格预审VS评标】</p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1760713055847.png" alt="image-20251017225735800" loading="lazy"></p><h3 id="考点3-合同计价方式【a】" tabindex="-1">考点3：合同计价方式【A】 <a class="header-anchor" href="#考点3-合同计价方式【a】" aria-label="Permalink to &quot;考点3：合同计价方式【A】&quot;">​</a></h3><p><strong>1.总价合同【明确、简单、短小】</strong></p><table><tbody><tr><td rowspan="2">分类</td><td>固定总价合同</td><td>建设单位没有要求变更原定承包内容的，均应按签约合同价支付；投标报<br>价一笔包死，施工单位承担主要风险，会报较高价格；<br>适用情形：<br>①已有施工图设计文件，施工任务和发包范围明确，合同履行中不会出现<br>较大设计变更<br>②工程规模较小、技术不太复杂的中小型工程或承包工作内容较为简单的<br>工程部位<br>③工程量小、工期较短(一般为1年之内),双方可不考虑市场价格浮动对<br>承包价格的影响</td></tr><tr><td>可调总价合同</td><td>适用情形：合同履行过程中市场价格变动、工程变更及其他工程条件变化<br>的情况【变】工期较长(1年以上)的工程常用调价方法有：<br>①文件证明法②票据价格调整法③公式调价法</td></tr></tbody></table><p><strong>2.单价合同【不明确、复杂、长大】</strong></p><table><tbody><tr><td>工程价款</td><td colspan="2">工程价款=所报单价×实际完成工程量<br> 工程量清单所列工程量=估算工程量(净量)≠实际工程量</td></tr><tr><td>适用情形</td><td colspan="2">①用于工期长、技术复杂、实施过程中发生各种不可预见因素较多的大型工程；<br> ②初步设计完成后就进行招标的工程。</td></tr><tr><td rowspan="2">分类</td><td>固定单价合同</td><td>无论发生哪些影响价格的因素，都不调价施工单位存在一定风险</td></tr><tr><td>可调单价合同</td><td>调价情形：①实际工程量的变化超过一定比例②市场价格变化达到一定<br> 程度③国家政策发生变化【正常量】<br> 施工单位的风险相对较小</td></tr></tbody></table><p><strong>3.成本加酬金合同</strong></p><table><tbody><tr><td colspan="2">适用情形</td><td>边设计、边施工紧急工程或灾后修复工程</td></tr><tr><td rowspan="4">分类</td><td>成本加固定百分比酬金</td><td>酬金随着直接成本的增加而增加【奖金越来越多】不能激励施工单位缩短<br> 工期和降低成本</td></tr><tr><td>成本加固定酬金</td><td>酬金为某一固定值【奖金就那么多】<br> 不能鼓励施工单位关心降低直接成本，施工单位会关心缩短工期</td></tr><tr><td>成本加浮动酬金</td><td>预期成本+固定酬金+浮动奖惩(限额为基本酬金)【罚款有底线】预期成本<br> 估算较为困难<br> ①实际成本=预期成本②实际成本&lt;预期成本③实际成本&gt;预期成本能促使<br> 施工单位关心成本降低和缩短工期，双方都没有太大风险</td></tr><tr><td>目标成本加奖罚</td><td>百分比形式约定基本酬金和奖罚酬金【罚款没有底线】<br> ①直接成本&gt;目标成本界限(5%),扣罚金；<br> ②直接成本有节约，加酬金；还可约定工期奖罚计算办法<br> 有利于鼓励施工单位降低成本和缩短工期，双方都没有太大风险</td></tr></tbody></table><p>4.合同计价方式比较</p><p>施工单位承担的风险：总价合同＞单价合同＞成本加酬金合同；固定百分比酬金＜固</p><p>定酬金＜浮动酬金＜奖罚。</p><table align="center"><tbody><tr><td rowspan="2">合同类型</td><td rowspan="2">总价<br>合同</td><td rowspan="2">单价<br> 合同</td><td colspan="4">成本加酬金合同</td></tr><tr><td>成本加固定<br> 百分比酬金</td><td>成本加<br> 固定酬金</td><td>成本加<br> 浮动酬金</td><td>目标成本加<br> 奖罚</td></tr><tr><td>应用范围</td><td>广泛</td><td>广泛</td><td colspan="3">有局限性</td><td>某些情形</td></tr><tr><td>建设单位对造价控制</td><td>易</td><td>较易</td><td>最难</td><td>难</td><td>不易</td><td>有可能</td></tr><tr><td>施工单位风险</td><td>大</td><td>小</td><td colspan="2">基本没有</td><td>不大</td><td>有</td></tr></tbody></table>',40)])])}const g=d(o,[["render",e]]);export{_ as __pageData,g as default};
